.ds-btn-primary { font-family:Helvetica,Arial,sans-serif;transition:background .15s,color .15s,border-color .15s;display:inline-flex;align-items:center;justify-content:center;gap:12px;padding:0 20px;font-weight:500;
  min-height: 44px;
  border-radius: 3px;
  font-size: 12px;
  white-space: nowrap;background: #1c1c1c;
  color: #ffffff;
  border: 1px solid #1c1c1c; } .ds-btn-primary:hover {background: #3d3d3d;
  border-color: #3d3d3d; } .ds-btn-primary:focus-visible { outline: 2px solid #777777; outline-offset: 4px; } .ds-btn-primary:disabled { opacity:.4;cursor:not-allowed; }

.ds-btn-secondary { font-family:Helvetica,Arial,sans-serif;transition:background .15s,color .15s,border-color .15s;display:inline-flex;align-items:center;justify-content:center;gap:12px;padding:0 20px;font-weight:500;
  min-height: 44px;
  border-radius: 3px;
  font-size: 12px;
  white-space: nowrap;background: #ffffff;
  color: #252525;
  border: 1px solid #cecece; } .ds-btn-secondary:hover {background: #f3f3f3; } .ds-btn-secondary:focus-visible { outline: 2px solid #777777; outline-offset: 4px; } .ds-btn-secondary:disabled { opacity:.4;cursor:not-allowed; }

.ds-btn-ghost { font-family:Helvetica,Arial,sans-serif;transition:background .15s,color .15s,border-color .15s;display:inline-flex;align-items:center;justify-content:center;gap:12px;padding:0 20px;font-weight:500;
  min-height: 44px;
  border-radius: 3px;
  font-size: 12px;
  white-space: nowrap;background: none;
  color: #545454;
  padding: 0 7px;
  min-height: 44px; } .ds-btn-ghost:hover {background: #f3f3f3; } .ds-btn-ghost:focus-visible { outline: 2px solid #777777; outline-offset: 4px; } .ds-btn-ghost:disabled { opacity:.4;cursor:not-allowed; }

.ds-field { display:flex;flex-direction:column;gap:8px;font:14px/1.5 Helvetica,Arial,sans-serif;color:var(--ink); } .ds-field span {font-size: 12px;
  color: #555555;} .ds-field input {width: 100%;
  min-height: 46px;
  padding: 12px 13px;
  border: 1px solid #cdcdcd;
  border-radius: 3px;
  background: #ffffff;
  font-size: 14px;
  transition: border-color 0.15s;color:var(--ink);font-family:inherit;font-variant-numeric:tabular-nums;} .ds-field input:focus {border-color: #565656;
  outline: 1px solid #565656;
  outline-offset: 0;}

.ds-tabs {display: flex;
  align-self: stretch;
  gap: 21px;font-family:Helvetica,Arial,sans-serif;} .ds-tabs button {background:transparent;border:0;display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 1px;
  min-height: 47px;
  font-size: 12px;
  color: #737373;
  border-bottom: 2px solid transparent;} .ds-tabs button.ds-selected {color: #181818;
  border-color: #181818;} .ds-tabs button:hover {color: #111111;} .ds-tabs button:focus-visible { outline: 2px solid #777777; outline-offset: 4px; }

.ds-rail {background:#1c1c1c;padding:21px;} .ds-destination {border:0;background:transparent;font-family:Helvetica,Arial,sans-serif;display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 0 11px;
  min-height: 43px;
  text-align: left;
  font-size: 12px;
  color: #bfbfbf;
  border-radius: 3px;} .ds-destination:hover {background: #303030;
  color: #ffffff;} .ds-destination:focus-visible { outline: 2px solid #777777; outline-offset: 4px; }

.ds-tag {font-family:Helvetica,Arial,sans-serif;display: inline-block;
  border: 1px solid #dbdbdb;
  padding: 6px 10px;
  font-size: 10px;
  color: #737373;
  white-space: nowrap;
  border-radius: 2px;}

.ds-section {font:14px/1.5 Helvetica,Arial,sans-serif;color:var(--ink);margin-bottom: 29px;
  padding: 26px 0;
  border-top: 1px solid #262626;
  min-width: 0;} .ds-section h2 {font-size:18px;font-weight:500;margin:0 0 23px;} .ds-section p {margin:0;}

.ds-row {font-family:Helvetica,Arial,sans-serif;background:transparent;border:0;color:var(--ink);display: grid;
  grid-template-columns: minmax(0, 1fr) 48px 48px 48px;
  gap: 12px;
  align-items: center;display: grid;
  grid-template-columns: minmax(0, 1fr) 48px 48px 48px;
  gap: 12px;
  align-items: center;} .ds-row>span:not(:first-child){text-align:right;} .ds-exercise {display: flex;
  align-items: center;
  gap: 17px;
  min-width: 0;} .ds-exercise>span {font-size: 10px;
  color: #737373;} .ds-exercise>strong {font-size: 13px;
  font-weight: 400;
  line-height: 1.5;} .ds-row:hover {background: #f7f7f7;} .ds-row:focus-visible { outline: 2px solid #777777; outline-offset: 4px; }
